 rows.append(dict(key=key,allowance_usd=r['allowance_usd'],state=r['state'],execution=e,execution_state=st['state'],execution_end_time=st.get('endTime'),checks=checks,inventory=own,completion=completion,permission=permission,cost=cost,all_audit_checks_pass=all(checks.values())))
